def main():
    OUT.mkdir(parents=True, exist_ok=True)
    dimensions = {
        "花字": ["标题层级", "动态文字", "字幕安全区"], "贴图": ["图形叠加", "画面层级", "信息卡布局"],
        "特效": ["转场", "运动图形", "视觉揭示"], "滤镜": ["色彩", "曝光", "对比度"],
        "生活实拍": ["生活场景", "人物动作", "镜头覆盖", "构图"], "口播": ["人物表达", "竖屏构图", "视线与手势"],
        "商品与美妆": ["商品展示", "微距景别", "材质与光线", "留白"], "美食制作": ["过程镜头", "手部动作", "食物特写", "动作节奏"],
        "运动与动作": ["动作连续性", "运动节奏", "全身构图"], "舞蹈与表演": ["身体动作", "表演节奏", "全身构图", "光影"],
        "动作剪辑": ["动作匹配", "切点选择", "运动方向连续", "景别切换"],
        "自然与旅行": ["航拍运镜", "空间揭示", "远景构图"], "城市与建筑": ["城市空镜", "延时摄影", "空间层次"],
        "访谈与职场": ["访谈覆盖", "人物视线", "对话反应镜头"], "旅行与人物": ["跟拍运镜", "人物互动", "环境交代"],
        "宠物与动物": ["动物动作", "反应时机", "不可预测运动"], "教育与讲解": ["演示镜头", "讲解结构", "信息节奏"],
        "社交与轻喜剧": ["多人互动", "反应镜头", "笑点节奏"],
        "电影镜头与剪辑": ["镜头尺度", "空间调度", "影调", "视线连续性", "剪辑节奏", "叙事信息"],
        "短视频平台风格代理": ["竖屏安全区", "口播构图", "注意力组织", "创作者场景", "移动端观看"],
    }
    dedup, rows = {}, []
    for item in ITEMS:
        key = item["media_url"].split("#", 1)[0]
        if key in dedup:
            continue
        dedup[key] = item["id"]
        item = {**item, "learning_dimensions": dimensions.get(item["category"], []),
                "media_sha256": item.get("media_sha256") or hashlib.sha256(key.encode()).hexdigest(),
                "evidence_role": item.get("evidence_role", "visual_observation_source"),
                "captured_locally": item.get("captured_locally", False),
                "checked_date": item.get("checked_date", "2026-10-02"),
                "dedup_key": item.get("dedup_key", "canonical_media_url_sha256"),
                "use_boundary": item.get("use_boundary", "Learn general composition/motion/color relationships only. Do not copy identifiable template, typography artwork or source asset into production.")}
        rows.append(item)
    (OUT / "visual-sources.jsonl").write_text("".join(json.dumps(r, ensure_ascii=False) + "\n" for r in rows), encoding="utf-8")
    by_category = {}
    for row in rows: by_category.setdefault(row["category"], []).append(row)
    studies_path = OUT / "paired-samples/studies.jsonl"
    studies = [json.loads(line) for line in studies_path.read_text(encoding="utf-8").splitlines() if line.strip()] if studies_path.is_file() else []
    complete_studies = [row for row in studies if row.get("status") == "framewise_vision_complete"]
    local_visual_studies = []
    for study_path in (OUT / "external-datasets").rglob("visual-study.json"):
        try:
            study = json.loads(study_path.read_text(encoding="utf-8"))
            if study.get("ai_rag_eligible") is True and study.get("human_review_status") == "reviewed_source_video_and_sampled_frames":
                local_visual_studies.append(study)
        except (OSError, json.JSONDecodeError):
            continue
    short_video_studies = [row for row in complete_studies if row.get("platform_scope") == "short_video_style_proxy"]
    (OUT / "summary.json").write_text(json.dumps({"version":"web-visual-sources-v1","unique_visual_sources":len(rows),
        "categories":{k:len(v) for k,v in sorted(by_category.items())},"video_sources":sum(r["media_type"] in {"video_source_page", "video_gallery_page", "video_with_reviewed_frames"} for r in rows),
        "image_or_preview_sources":sum(r["media_type"] not in {"video_source_page", "video_gallery_page", "video_with_reviewed_frames"} for r in rows),"dedup":"canonical media URL SHA-256",
        "paired_visual_studies_complete":len(complete_studies),
        "paired_study_video_count":len(complete_studies),
        "paired_study_frame_count":sum(len(r.get("frame_observations",[])) for r in complete_studies),
        "paired_study_model":"GLM-4.6V-Flash local vision model" if complete_studies else None,
        "locally_reviewed_video_frame_studies":len(local_visual_studies),
        "locally_reviewed_video_frame_count":sum(len(r.get("frames", [])) for r in local_visual_studies),
        "downloaded_study_video_count":len(complete_studies),"repackaged_for_production":False,"visual_review_complete":False,
        "study_scopes":{scope:sum(r.get("platform_scope")==scope for r in complete_studies)
                        for scope in sorted({r.get("platform_scope") for r in complete_studies if r.get("platform_scope")})},
        "short_video_style_types":{kind:sum(r.get("style_type")==kind for r in short_video_studies)
                                   for kind in sorted({r.get("style_type") for r in short_video_studies if r.get("style_type")})},
        "platform_native_samples":0,
        "note":"Source-page curation and timestamped local video/frame studies are tracked separately. Film and short-video items are style proxies, not platform-native Douyin/Bilibili samples. Retrieved rules are derived observations, not fine-tuning or finished-video quality guarantees."},ensure_ascii=False,indent=2),encoding="utf-8")
    cards=[]
    for row in rows:
        if row['media_type'] == 'video_with_reviewed_frames':
            visual = "<a class='video' href='paired-samples/index.html'>▶ 播放本机已核验样片</a>"
        elif row['media_type'] in {'video_source_page','video_gallery_page'}:
            visual = f"<a class='video' href='{html.escape(row['source_url'],quote=True)}' target='_blank'>▶ 打开源视频 / 视频画廊</a>"
        else:
            visual = f"<a href='{html.escape(row['source_url'],quote=True)}' target='_blank'><img loading='lazy' src='{html.escape(row['media_url'],quote=True)}' alt='{html.escape(row['title'])}'></a>"
        cards.append(f"<article>{visual}<h2>{html.escape(row['title'])}</h2><p><b>{html.escape(row['category'])} · {html.escape(row['style'])}</b></p><p>{html.escape(row['source_note'])}</p><small>{html.escape(row['evidence_status'])} | {html.escape(row['license_status'])}</small><p><a href='{html.escape(row['source_url'],quote=True)}' target='_blank'>打开原始来源页 ↗</a></p></article>")
    page="<!doctype html><html lang='zh-CN'><meta charset='utf-8'><meta name='viewport' content='width=device-width'><title>AI CUT 全类型视觉样本</title><style>body{font:16px system-ui;background:#f4f5f7;color:#222;margin:24px}h1{max-width:1200px;margin:auto}main{max-width:1200px;margin:22px auto;display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:18px}article{background:white;border-radius:12px;padding:14px;box-shadow:0 2px 12px #0001}.video{height:158px;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#172554,#334155);color:white;border-radius:8px;text-decoration:none;font-size:20px}img{width:100%;aspect-ratio:16/10;object-fit:contain;background:#e9ebef;border-radius:8px}small{color:#666}</style><h1>AI CUT 全类型视觉样本：视频与画面</h1><p style='max-width:1200px;margin:10px auto'>按题材、表演、镜头与视觉包装拓展。视频卡片直接进入源视频页；图片由原站远程呈现。来源页核验不等于逐帧审看。抖音/B站条目用于追踪平台原生样本；电影和短视频创作场景另标为风格代理，不冒充平台作品。</p><p style='max-width:1200px;margin:10px auto'><a href='paired-samples/index.html'>查看已完成的视频 + 时间码图片帧 + 本地视觉分析成套样例 ↗</a></p><main>"+"\n".join(cards)+"</main></html>"
    (OUT / "index.html").write_text(page, encoding="utf-8")
    print(json.dumps({"unique_visual_sources":len(rows),"categories":{k:len(v) for k,v in sorted(by_category.items())},"index":str(OUT/"index.html")},ensure_ascii=False,indent=2))


if __name__ == "__main__":
    main()
